import test from 'node:test';
import assert from 'node:assert/strict';
import { moduleHarness } from '../compose-kit/kit.mjs';

const fulfilment = moduleHarness('fulfilment');
const key = 'ORD-1-F1';
const NOW = '2026-03-02T10:00:00+01:00';
const files = {};
const fInput = {
