      if (again(true)) eff.push({ key: 'ship', system: 'carrier', op: 'create', args: fixed }); else { S.sh = 'bad'; fail(); }
    } else if (c === 'bad') { S.sh = 'bad'; fail(); }
    else if (c === 'transient' && S.fx < MAX_FIX) { S.fx += 1; eff.push({ key: 'ship', system: 'carrier', op: 'create', args: shipArgs(S) }); }
    else if (c === 'transient') { S.sh = 'bad'; fail(); }
  }
