  for (const k of Object.keys(v)) (props.includes(k) ? (out[k] = fixArgs(v[k], s.properties[k])) : extra.push(k));
  const missing = (s.required ?? []).filter(k => !(k in out));
  extra.forEach((k, i) => { if (missing[i]) out[missing[i]] = fixArgs(v[k], s.properties[missing[i]]); });
  return out;
};
